//! Parity level L1: every `pycompat` module against CPython reference
//! vectors (`tests/vectors/*.json`, generated by
//! `scripts/parity/vectors.py`; regenerate with `cargo xtask vectors`).

use std::path::PathBuf;

use pycompat::json::{self, Value};
use pycompat::pyfmt;
use pycompat::pyrepr;
use pycompat::random::PyRandom;
use pycompat::stats;
use serde::Deserialize;

fn vector_file(name: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/vectors")
        .join(name);
    std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("reading {}: {e}", path.display()))
}

/// Convert a `serde_json::Value` into the crate's ordered [`Value`].
fn to_value(v: &serde_json::Value) -> Value {
    match v {
        serde_json::Value::Null => Value::Null,
        serde_json::Value::Bool(b) => Value::Bool(*b),
        serde_json::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Value::Int(i128::from(i))
            } else if let Some(u) = n.as_u64() {
                Value::Int(i128::from(u))
            } else {
                // beyond u64: the vector file keeps the exact digits
                n.to_string().parse::<i128>().map_or_else(
                    |_| Value::Float(n.as_f64().expect("a JSON number")),
                    Value::Int,
                )
            }
        }
        serde_json::Value::String(s) => Value::Str(s.clone()),
        serde_json::Value::Array(items) => Value::List(items.iter().map(to_value).collect()),
        serde_json::Value::Object(map) => {
            Value::Dict(map.iter().map(|(k, v)| (k.clone(), to_value(v))).collect())
        }
    }
}

// ----------------------------------------------------------------- random

#[derive(Deserialize)]
struct RandrangeCase {
    n: u128,
    value: u128,
}

#[derive(Deserialize)]
struct ShuffleCase {
    size: usize,
    order: Vec<usize>,
}

#[derive(Deserialize)]
struct BitsCase {
    k: u32,
    value: String,
}

#[derive(Deserialize)]
struct SharedStream {
    shuffles: Vec<Vec<usize>>,
    then_randrange_4: u128,
}

#[derive(Deserialize)]
struct RandomVector {
    seed: i128,
    getrandbits32: Vec<u32>,
    random: Vec<f64>,
    randrange: Vec<RandrangeCase>,
    shuffles: Vec<ShuffleCase>,
    getrandbits: Vec<BitsCase>,
    shared_stream: SharedStream,
}

#[test]
fn random_matches_cpython() {
    let vectors: Vec<RandomVector> =
        serde_json::from_str(&vector_file("random.json")).expect("random.json parses");
    assert!(vectors.len() >= 10);
    for v in &vectors {
        let mut rng = PyRandom::new(v.seed);
        let words: Vec<u32> = (0..v.getrandbits32.len())
            .map(|_| rng.genrand_u32())
            .collect();
        assert_eq!(
            words, v.getrandbits32,
            "getrandbits(32) stream for seed {}",
            v.seed
        );

        let mut rng = PyRandom::new(v.seed);
        let floats: Vec<f64> = (0..v.random.len()).map(|_| rng.random()).collect();
        assert_eq!(floats, v.random, "random() stream for seed {}", v.seed);

        let mut rng = PyRandom::new(v.seed);
        for case in &v.randrange {
            assert_eq!(
                rng.randrange(case.n),
                case.value,
                "randrange({}) seed {}",
                case.n,
                v.seed
            );
        }

        for case in &v.shuffles {
            let mut rng = PyRandom::new(v.seed);
            let mut items: Vec<usize> = (0..case.size).collect();
            rng.shuffle(&mut items);
            assert_eq!(
                items, case.order,
                "shuffle of {} items, seed {}",
                case.size, v.seed
            );
        }

        for case in &v.getrandbits {
            let mut rng = PyRandom::new(v.seed);
            let expected: u128 = case.value.parse().expect("vector value fits u128");
            assert_eq!(
                rng.getrandbits(case.k),
                expected,
                "getrandbits({}) seed {}",
                case.k,
                v.seed
            );
        }

        let mut rng = PyRandom::new(v.seed);
        for (size, expected) in [7usize, 5, 9].iter().zip(&v.shared_stream.shuffles) {
            let mut items: Vec<usize> = (0..*size).collect();
            rng.shuffle(&mut items);
            assert_eq!(&items, expected, "shared stream shuffle, seed {}", v.seed);
        }
        assert_eq!(
            rng.randrange(4),
            v.shared_stream.then_randrange_4,
            "seed {}",
            v.seed
        );
    }
}

// ------------------------------------------------------------------- json

#[derive(Deserialize)]
struct JsonVector {
    value: serde_json::Value,
    dumps: String,
}

#[test]
fn dumps_matches_cpython() {
    let vectors: Vec<JsonVector> =
        serde_json::from_str(&vector_file("json.json")).expect("json.json parses");
    for v in &vectors {
        assert_eq!(
            json::dumps(&to_value(&v.value)),
            v.dumps,
            "json.dumps of {:?}",
            v.value
        );
    }
}

// ----------------------------------------------------------------- format

#[derive(Deserialize)]
struct FormatVector {
    kind: String,
    value: serde_json::Value,
    spec: String,
    text: String,
}

#[test]
fn format_matches_cpython() {
    let vectors: Vec<FormatVector> =
        serde_json::from_str(&vector_file("format.json")).expect("format.json parses");
    for v in &vectors {
        let got = match v.kind.as_str() {
            "float" => pyfmt::format_float(v.value.as_f64().expect("float"), &v.spec),
            "repr" => pycompat::pyfloat::repr(v.value.as_f64().expect("float")),
            "int" => pyfmt::format_int(i128::from(v.value.as_i64().expect("int")), &v.spec),
            "str" => pyfmt::format_str(v.value.as_str().expect("str"), &v.spec),
            other => panic!("unknown vector kind {other}"),
        };
        assert_eq!(got, v.text, "format({:?}, {:?})", v.value, v.spec);
    }
}

// ------------------------------------------------------------------ stats

#[derive(Deserialize)]
struct RateCase {
    wins: Vec<i64>,
    games: i64,
    mean: f64,
    stdev: f64,
}

#[derive(Deserialize)]
struct TurnsCase {
    turns: Vec<i64>,
    mean: f64,
    median: f64,
}

#[derive(Deserialize)]
struct StatsVectors {
    rates: Vec<RateCase>,
    turns: Vec<TurnsCase>,
}

#[test]
fn statistics_match_cpython() {
    let vectors: StatsVectors =
        serde_json::from_str(&vector_file("stats.json")).expect("stats.json parses");
    for case in &vectors.rates {
        #[expect(
            clippy::cast_precision_loss,
            reason = "the Python code does w / games in floats"
        )]
        let rates: Vec<f64> = case
            .wins
            .iter()
            .map(|&w| w as f64 / case.games as f64)
            .collect();
        assert_eq!(
            stats::mean(&rates),
            case.mean,
            "mean of {:?}/{}",
            case.wins,
            case.games
        );
        if rates.len() > 1 {
            assert_eq!(
                stats::stdev(&rates),
                case.stdev,
                "stdev of {:?}/{}",
                case.wins,
                case.games
            );
        }
    }
    for case in &vectors.turns {
        #[expect(clippy::cast_precision_loss, reason = "turn counts are small integers")]
        let turns: Vec<f64> = case.turns.iter().map(|&t| t as f64).collect();
        assert_eq!(stats::mean(&turns), case.mean, "mean of {:?}", case.turns);
        assert_eq!(
            stats::median(&turns),
            case.median,
            "median of {:?}",
            case.turns
        );
    }
}

// ------------------------------------------------------------------- repr

#[derive(Deserialize)]
struct ReprVector {
    value: serde_json::Value,
    repr: String,
}

#[test]
fn repr_matches_cpython() {
    let vectors: Vec<ReprVector> =
        serde_json::from_str(&vector_file("repr.json")).expect("repr.json parses");
    for v in &vectors {
        assert_eq!(
            pyrepr::repr(&to_value(&v.value)),
            v.repr,
            "repr of {:?}",
            v.value
        );
    }
}
